-- H2-05 Pharma OA schema completion. Normal uninstall policy: retain.
CREATE TABLE IF NOT EXISTS pharma_oa_announcements (id VARCHAR(64) PRIMARY KEY, kind VARCHAR(32) NOT NULL, title VARCHAR(255) NOT NULL, content LONGTEXT NOT NULL, status VARCHAR(32) NOT NULL, published_by VARCHAR(64) NOT NULL DEFAULT '', published_at DATETIME(3) NULL, audience_json LONGTEXT NOT NULL, documents_json LONGTEXT NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', updated_by VARCHAR(64) NOT NULL DEFAULT '', KEY idx_pharma_announcements_status_published(status,published_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS pharma_oa_cold_chain_records (id VARCHAR(64) PRIMARY KEY, balance_id VARCHAR(64) NOT NULL, product_id VARCHAR(64) NOT NULL, batch_id VARCHAR(64) NOT NULL, batch_no VARCHAR(128) NOT NULL, warehouse_id VARCHAR(64) NOT NULL, area_id VARCHAR(64) NOT NULL, location_id VARCHAR(64) NOT NULL, temperature_celsius DOUBLE NOT NULL, humidity_percent DOUBLE NOT NULL, min_celsius DOUBLE NOT NULL, max_celsius DOUBLE NOT NULL, recorded_at DATETIME(3) NOT NULL, source VARCHAR(64) NOT NULL, payload_json LONGTEXT NOT NULL, created_at DATETIME(3) NOT NULL, created_by VARCHAR(64) NOT NULL DEFAULT '', KEY idx_pharma_cold_chain_batch_time(batch_id,recorded_at), KEY idx_pharma_cold_chain_warehouse_time(warehouse_id,recorded_at)) ENGINE=InnoDB;
